function practice(filter){const wrong=filter==='wrong';const id=/^[0-9]$/.test(filter)?Number(filter):0;const ids=wrong?wrongIds():lessons[id].checks.map((q,j)=>`${id}-${j}`);return `${heading('把「好像懂了」变成「真的会了」。','30 道概念与计算题，逐题解析；错题自动收进复习列表。','PRACTICE MAKES UNDERSTANDING')}<div class="row" style="margin-bottom:20px;align-items:flex-start;flex-wrap:wrap"><div class="pill-tabs" style="margin:0"><a href="#practice/${id}" class="${!wrong?'active':''}">按课程练习</a><a href="#practice/wrong" class="${wrong?'active':''}">错题复习 <span class="tag">${wrongIds().length}</span></a></div>${!wrong?`<select id="practice-select" aria-label="选择练习课程" style="width:auto;max-width:100%">${lessons.map(l=>`<option value="${l.id}" ${l.id===id?'selected':''}>${String(l.id+1).padStart(2,'0')} · ${l.title}</option>`).join('')}</select>`:''}</div><div class="panel row"><div><h3>${wrong?'重新思考，直到想明白':lessons[id].title}</h3><p class="subtitle">已保存 ${state.attempts.length} 次答题记录 · ${passedCount()} 节课程通过全部题目</p></div>${!wrong?link('回看课程 →',`lesson/${id}`,'soft'):''}</div>${quizView(ids,wrong?'你的待复习题目':'准备好了吗？')}<details style="margin-top:25px"><summary>最近答题记录（最多 10 次）</summary>${state.attempts.length?state.attempts.slice(-10).reverse().map(a=>`<div class="row small" style="padding:12px 0;border-bottom:1px solid var(--line);color:var(--muted)"><span>${new Date(a.date).toLocaleString('zh-CN')}</span><span>${Object.entries(a.answers).filter(([k,v])=>isCorrect(k,v)).length} / ${Object.keys(a.answers).length} 正确</span></div>`).join(''):'<p class="subtitle">完成首次练习后，记录会出现在这里。</p>'}</details>`;}

function assignmentList(){return `${heading('让知识，经过你的双手。','从纸笔计算到最小语言模型，把理解留在可验证的成果里。','BUILD YOUR UNDERSTANDING')}<div class="assignment-grid">${assignments.map(a=>{const w=state.work[a.id];return `<article class="panel assignment-card"><div class="row"><span class="color-icon ${stages[a.id].color}">${icon(a.id<2?'edit':'code',21)}</span><span class="tag ${w?.submitted?'green':''}">${w?.submitted?'已自评提交':w?.body?'草稿已保存':'尚未开始'}</span></div><div class="eyebrow">ASSIGNMENT 0${a.id+1} · ${a.level}</div><h3>${a.title}</h3><p>${esc(a.preview||a.brief.slice(0,88))}…</p><div class="row"><span class="muted small">${icon('clock',13)} ${a.time}</span>${link(`进入作业 ${icon('arrow',13)}`,`assignment/${a.id}`,'soft')}</div></article>`}).join('')}</div><div class="callout"><strong>如何完成作业？</strong>先独立作答，再查看参考思路并按验收清单自评。作业记录只保存在本地；提交表示你完成了自评，不代表教师或 AI 自动批改。代码在你自己的 Python 环境运行。</div>`;}
function assignment(id){const a=assignments[id];if(!a)return notFound();const w=state.work[id]||{body:'',checks:[],submitted:null};return `<div class="row" style="margin-bottom:22px"><a class="link" href="#assignments">${icon('back',14)} 返回我的作业</a><span class="tag">${a.level} · ${a.time}</span></div>${heading(a.title,mathText(a.deliver),`ASSIGNMENT 0${id+1}`)}<div class="lesson-layout"><div><div class="panel"><h3>任务说明</h3><p class="subtitle" style="line-height:2;font-size:13px">${mathText(a.brief)}</p><div class="callout"><strong>一个小提示</strong>${mathText(a.hint)}</div><div class="actions">${a.lessons.map(i=>link(`第 ${i+1} 课`, `lesson/${i}`,'soft small')).join('')}${id===2?btn(`${icon('download',13)} 下载可运行参考脚本`,'download-python','secondary small'):''}</div></div><div class="panel" style="margin-top:20px"><div class="row" style="margin-bottom:18px"><h3>你的解答与实验记录</h3><span id="save-indicator" class="save-indicator">${storageOK?'已自动保存到本地':'仅暂存于本页面'}</span></div><label class="visually-hidden" for="work-body">作业解答</label><textarea id="work-body" class="work-editor" data-id="${id}" placeholder="写下你的推导、粘贴代码和运行结果，或解释你遇到的问题……" maxlength="100000">${esc(w.body)}</textarea><div class="row" style="margin-top:12px"><span class="muted small" id="work-status">${w.submitted?`已于 ${dateText(w.submitted)} 自评提交`:'草稿 · 输入后自动保存'}</span>${btn('完成自评并提交','submit-work','primary',`data-id="${id}"`)}</div><details><summary>独立尝试后，再展开参考思路</summary><div class="reference-solution ${id===2?'no-math code-solution':''}">${id===2?esc(a.solution):mathText(a.solution)}</div></details></div></div><aside class="lesson-aside"><div class="goal-box"><h4>${icon('check',15)} 验收清单</h4><p>对照自己的成果逐项确认，全部满足后提交。</p>${a.rubric.map((r,i)=>`<label class="rubric-label"><input type="checkbox" data-work-check="${id}" value="${i}" ${w.checks[i]?'checked':''}><span>${mathText(r)}</span></label>`).join('')}</div><div class="callout"><strong>提交 ≠ 自动批改</strong>这里记录你的自评结果。请用实际计算和测试输出验证，而不是仅凭阅读参考答案勾选。</div></aside></div>`;}

let noteSearch='';
function notes(id){const n=state.notes.find(n=>n.id===id)||state.notes[0];return `${heading('留住每一次「原来如此」。','把概念写成自己的话，让疑问成为下一次探索的起点。','YOUR SECOND BRAIN',btn(`${icon('plus',14)} 新建笔记`,'new-note','primary'))}<div class="notes-layout"><div class="note-list no-math"><div class="search-box"><label class="visually-hidden" for="note-search">搜索笔记</label><input id="note-search" class="field" placeholder="搜索标题或正文…" value="${esc(noteSearch)}"></div><div id="note-items">${noteItems(n?.id)}</div></div><section class="panel" id="note-pane">${n?`<div class="row"><span class="tag">${icon('note',12)} 学习笔记</span><span id="save-indicator" class="save-indicator">已自动保存到本地</span></div><label class="visually-hidden" for="note-title">笔记标题</label><input id="note-title" class="note-title" data-id="${n.id}" value="${esc(n.title)}" placeholder="给这个想法起个名字" maxlength="150"><div class="row"><label class="form-label" for="note-lesson" style="margin:0;white-space:nowrap">关联课程</label><select id="note-lesson" data-id="${n.id}" style="font-size:11px;padding:7px 10px;max-width:310px"><option value="">自由笔记</option>${lessons.map(l=>`<option value="${l.id}" ${n.lesson===l.id?'selected':''}>${String(l.id+1).padStart(2,'0')} · ${l.title}</option>`).join('')}</select></div><label class="visually-hidden" for="note-body">笔记正文</label><textarea class="note-editor" id="note-body" data-id="${n.id}" maxlength="100000" placeholder="我理解的核心概念是……\n\n一个让我想明白的例子……\n\n我还没想清楚的问题……">${esc(n.body)}</textarea><div id="note-preview" class="note-math-preview" hidden></div><div class="row" style="border-top:1px solid var(--line);padding-top:18px;flex-wrap:wrap"><span class="muted small no-math">支持 LaTeX：\\(行内公式\\) · \\[独立公式\\]</span><div class="actions">${btn('预览公式','preview-note','soft small')}${btn(`${icon('download',13)} 导出笔记`,'export-note','secondary small',`data-id="${n.id}"`)}${btn(icon('trash',14),'delete-note','secondary small',`data-id="${n.id}" aria-label="删除当前笔记"`)}</div></div>`:`<div class="empty-state" style="padding-top:90px">${icon('note',38)}<h3>知识，从自己的表达开始。</h3><p>写下一条笔记，或在课程页面点击「记录本课笔记」。<br>你可以关联课程、搜索内容，并导出到自己的设备。</p>${btn('写下第一条笔记','new-note','primary')}</div>`}</section></div>`;}
function noteItems(active){const filtered=state.notes.filter(n=>(n.title+' '+n.body).toLowerCase().includes(noteSearch.toLowerCase()));return filtered.length?filtered.map(n=>`<a href="#notes/${n.id}" class="note-item ${n.id===active?'active':''}"><h3>${esc(n.title||'未命名笔记')}</h3><p>${esc(n.body.slice(0,60)||'等待一个新想法…')}</p><small>${dateText(n.updated)}${n.lesson!==null?` · 第 ${n.lesson+1} 课`:''}</small></a>`).join(''):`<div class="empty-state" style="padding:28px 15px"><p>${noteSearch?'没有找到匹配的笔记。':'你的第一条笔记，会出现在这里。'}</p></div>`;}

function settings(){return `${heading('你的学习，由你保存。','课程内容随网站加载，学习记录仅存储在当前浏览器中。','LOCAL FIRST')}<div class="settings-grid"><div class="panel"><span class="color-icon mint">${icon('shield',22)}</span><h3 style="margin-top:18px">本地保存，随时备份</h3><p>笔记、答题记录、作业草稿和学习进度保存在此站点的 localStorage。本站应用不把这些学习记录上传到服务器，也不调用 AI 接口。</p><p>不同浏览器、设备或站点地址之间不会自动同步。清除网站数据或使用无痕窗口，可能使记录丢失。建议定期导出 JSON 备份。</p><div class="actions">${btn(`${icon('download',15)} 导出全部记录`,'export-all','primary')}${btn(`${icon('upload',15)} 导入备份`,'import-all','secondary')}</div>${rawBroken?btn('导出无法读取的原始记录','export-raw','secondary','style="margin-top:12px"'):''}</div><div class="panel"><h3>当前设备的学习记录</h3>${[['阅读完成',`${state.read.length} / 10 课`],['测验通过',`${passedCount()} / 10 课`],['答题记录',`${state.attempts.length} 次`],['学习笔记',`${state.notes.length} 篇`],['自评作业',`${Object.values(state.work).filter(w=>w.submitted).length} / 4 份`],['有学习活动的日期',`${state.days.length} 天`]].map(([k,v])=>`<div class="row" style="font-size:12px;padding:13px 0;border-bottom:1px solid var(--line)"><span class="muted">${k}</span><span>${v}</span></div>`).join('')}<p>导入会替换当前记录，操作前会显示备份摘要并请求确认。不会合并重复记录。</p></div></div><div class="panel" style="margin-top:24px"><div class="row" style="flex-wrap:wrap"><div><h3>重新开始学习</h3><p class="subtitle">仅清除此浏览器中的 Attention Lab 学习记录，建议先导出备份。</p></div>${btn('清空本地学习记录','reset-data','danger')}</div></div>`;}
function resources(){return `${heading('一份更扎实的学习指南。','先建立可计算的理解，再走进论文与真实实现。','KEEP EXPLORING')}<div class="lesson-layout"><article class="panel resources"><h2>推荐的学习方式</h2><ol><li><b>先预测。</b>调整参数前，先猜权重、形状或输出会怎样变化。</li><li><b>再观察。</b>用实验验证猜测，检查数值与公式是否一致。</li><li><b>自己解释。</b>不用术语堆砌，用具体例子写出输入、运算和输出。</li><li><b>独立完成。</b>做测验与作业，对照解析找出误解，回到课程再验证。</li></ol><h2 style="margin-top:30px">从原始资料继续探索</h2><a href="https://arxiv.org/html/1706.03762v7" target="_blank" rel="noopener noreferrer">01 · Attention Is All You Need — 原始论文 ↗</a><p>了解 encoder-decoder、缩放点积注意力、多头、FFN 与正弦位置编码的原始设计。课程明确区分原论文的 Post-LN 与作业使用的 Pre-LN。</p><a href="https://docs.pytorch.org/docs/stable/generated/torch.nn.functional.scaled_dot_product_attention.html" target="_blank" rel="noopener noreferrer">02 · PyTorch — Scaled Dot Product Attention ↗</a><p>对照官方接口检查缩放、mask 和 dropout。注意该接口布尔 mask 的 True 表示参与注意力，和 masked_fill 中 True 表示要填充的位置语义不同。</p><a href="https://docs.pytorch.org/docs/stable/generated/torch.nn.CrossEntropyLoss.html" target="_blank" rel="noopener noreferrer">03 · PyTorch — CrossEntropyLoss ↗</a><p>确认 logits、标签形状、忽略 padding 的方式，以及损失归约方法。</p><h2 style="margin-top:30px">实验边界与完成标准</h2><p>实验室使用小型、可检查的玩具张量。注意力的 Q/K/V 与采样 logits 是教学设定，不来自已训练语言模型；位置实验展示原始正弦方案。代码作业需要在本地 Python 环境运行，本站不执行或自动评分。</p><p>10 节课的测验全部答对，再独立完成 4 份作业，是本教程的建议完成标准。进度条只统计通过测验的课程，不把“看过”直接等同于“掌握”。</p></article><aside><div class="goal-box"><h4>这条路线的边界</h4><p>重点是 Transformer 核心计算与自回归语言建模。分布式训练、FlashAttention 内核、MoE 与完整大模型训练工程不在这条入门路线中。</p></div><div class="goal-box" style="margin-top:18px"><h4>一份可验证的参考</h4><p>下载最小因果注意力脚本，包含形状、归一化、遮罩和未来扰动测试。需先在本地安装 PyTorch。</p><div style="margin-top:15px">${btn(`${icon('download',13)} 下载 Python 脚本`,'download-python','soft small')}</div></div></aside></div>`;}
function notFound(){return `<div class="panel empty-state"><h1>这一页还没有内容</h1><p>请选择课程地图中的一个章节。</p>${link('回到学习概览','home')}</div>`;}

// All numerical experiments run locally; no model or external API is called.
export function softmax(a){const m=Math.max(...a);const ex=a.map(x=>Math.exp(x-m));const s=ex.reduce((a,b)=>a+b,0);return ex.map(x=>x/s);}
export function attention(Q,K,V,mask=false,temp=1){const scores=Q.map((q,i)=>K.map((k,j)=>mask&&j>i?-Infinity:q.reduce((s,x,d)=>s+x*k[d],0)/Math.sqrt(q.length)/temp));const weights=scores.map(softmax);return {scores,weights,out:weights.map(w=>V[0].map((_,d)=>w.reduce((s,x,j)=>s+x*V[j][d],0)))};}
let lab={type:'attention',query:2,head:0,mask:false,temp:1,qx:1,qy:1,vx:1,pos:3,dim:8,batch:2,tokens:8,model:64,heads:4,ff:256,decodeTemp:1,topk:4,samples:[]};
const tokens=['我','正在','学习','模型'];
const Qbase=[[[1,0],[0,1],[1,1],[2,.5]],[[.5,1],[1,-1],[0,1],[1,2]]];
const Kbase=[[[1,0],[0,1],[1,1],[2,-1]],[[0,1],[1,0],[-1,1],[1,2]]];
const labs=[['attention','注意力实验','Q/K/V · 权重 · 因果遮罩'],['position','位置编码','位置 · 频率 · 正弦与余弦'],['shape','张量形状','多头 · 残差 · FFN'],['decode','生成与采样','温度 · Top-k · 概率']];
function labsPage(type){if(!labs.some(l=>l[0]===type))type='attention';lab.type=type;return `${heading('动一下，理解就近了一点。','每个数字都能追踪，每次变化都有原因。先预测，再动手。','THE INTERACTIVE LAB',`<span class="tag">${icon('flask',13)} 在浏览器本地计算</span>`)}<div class="pill-tabs">${labs.map(([id,t])=>`<a href="#labs/${id}" class="${type===id?'active':''}">${t}</a>`).join('')}</div><div class="lab-layout"><div class="panel lab-controls">${labControls(type)}</div><div class="panel" id="lab-output"></div></div><div class="bottom-grid"><div class="panel"><h3>${icon('target',17)} 试着完成这个小挑战</h3><p class="subtitle" style="line-height:1.9;font-size:12px">${{attention:'选中「学习」，先预测开启因果遮罩后哪一列变成 0。再修改第一个 value 的数值，观察注意力权重是否变化、输出向量是否变化。',position:'观察位置 0 的编码。预测所有偶数维、奇数维各是什么，再把位置改成 1。为什么低频维度变化较慢？',shape:'把模型维度设置为 96，头数设为 6，再改成 8。观察每头维度。最后设置为 5，说明为什么这种等宽分头方式不合法。',decode:'先预测温度从 1 降到 0.3 时概率如何变化。再设 top-k=1，多次采样，解释结果为什么总是一样。'}[type]}</p><div class="actions" style="margin-top:17px">${btn(`${icon('note',14)} 记录实验观察`,'lab-note','soft')}${link('回看相关课程 →',`lesson/${{attention:4,position:2,shape:5,decode:9}[type]}`,'text')}</div></div><div class="panel"><h3>实验说明</h3><p class="subtitle" style="line-height:1.9;font-size:12px">${{attention:'这是一个每个 query/key 为 2 维的教学示例。两组头的 Q/K 为预设投影结果，并非训练模型。滑块只改变选中 query；每行单独归一化。标准注意力对应温度为 1。',position:'使用原论文的正弦位置编码，维度取偶数，位置从 0 开始。曲线显示第 0 维与第 1 维，色块展示所选位置的完整编码。',shape:'展示标准等宽多头、Pre-LN decoder-only block。这里的形状适用于 self-attention，cross-attention 的 Q/K 序列长度可以不同。',decode:'候选词与 logits 固定为 [2.4,1.6,0.8,0.2]，用于观察概率分布和随机抽样，不生成真实语言。温度必须大于 0，top-k 筛选后重新归一化。'}[type]}</p></div></div>`;}
function range(id,title,value,min,max,step=1){return `<div class="control"><label for="${id}">${title}<strong id="${id}-label">${value}</strong></label><input id="${id}" data-lab="${id}" type="range" min="${min}" max="${max}" step="${step}" value="${value}"></div>`;}
function labControls(type){if(type==='attention')return `<h3 style="margin-bottom:20px">从一个 Query 开始</h3><div class="control"><label>选择查询位置</label><div class="token-buttons">${tokens.map((t,i)=>`<button class="token-btn ${lab.query===i?'active':''}" data-action="query" data-id="${i}" aria-pressed="${lab.query===i}">${t}</button>`).join('')}</div></div><div class="control"><label for="head-select">观察不同的头</label><select id="head-select"><option value="0" ${lab.head===0?'selected':''}>Head 1 · 预设 A</option><option value="1" ${lab.head===1?'selected':''}>Head 2 · 预设 B</option></select></div>${range('qx','Query 第 1 维',lab.qx,-2,3,.1)}${range('qy','Query 第 2 维',lab.qy,-2,3,.1)}${range('temp','分布温度 τ',lab.temp,.2,2,.1)}${range('vx','V「我」的第 1 维',lab.vx,-2,4,.1)}<label class="switch-line"><input id="causal" type="checkbox" ${lab.mask?'checked':''}>启用因果遮罩</label><div class="actions" style="margin-top:20px">${btn(`${icon('refresh',13)} 重置实验`,'reset-lab','secondary small')}</div>`;
 if(type==='position')return `<h3 style="margin-bottom:20px">为位置生成一个签名</h3>${range('pos','序列位置 pos',lab.pos,0,31)}<div class="control"><label for="dim-select">编码维度 d</label><select id="dim-select">${[4,8,16].map(n=>`<option ${lab.dim===n?'selected':''} value="${n}">${n} 维</option>`).join('')}</select></div><div class="callout"><strong>维度成对出现</strong>偶数维用 sin，奇数维用 cos。每一对拥有相同频率。</div>`;
 if(type==='shape')return `<h3 style="margin-bottom:20px">配置一个最小 Block</h3>${range('batch','Batch size · B',lab.batch,1,8)}${range('tokens','序列长度 · T',lab.tokens,2,32)}<div class="control"><label for="model-select">模型维度 · ${math(String.raw`d_{\mathrm{model}}`)}</label><select id="model-select">${[32,64,96,128].map(n=>`<option value="${n}" ${lab.model===n?'selected':''}>${n}</option>`).join('')}</select></div>${range('heads','注意力头数 · h',lab.heads,1,8)}<div class="callout"><strong>常见约定</strong>${math(String.raw`d_{\mathrm{head}}=d_{\mathrm{model}}/h`)}<br>${math(String.raw`d_{\mathrm{ff}}=4d_{\mathrm{model}}`)}</div>`;
 return `<h3 style="margin-bottom:20px">下一个词，有哪些可能？</h3>${range('decodeTemp','采样温度 · τ',lab.decodeTemp,.1,2,.1)}${range('topk','保留候选数 · Top-k',lab.topk,1,4)}<div class="actions">${btn(`${icon('play',13)} 采样一次`,'sample','primary')}${btn('清空','clear-samples','secondary small')}</div><div class="callout"><strong>先看看分布</strong>相同参数下，随机采样也可能不同。Top-k=1 时只保留最高分候选。</div>`;
}
function renderLab(){const el=$('#lab-output');if(!el)return;const f=n=>n===-Infinity?'−∞':n.toFixed(3);
 if(lab.type==='attention'){const Q=Qbase[lab.head].map(x=>[...x]);Q[lab.query]=[lab.qx,lab.qy];const K=Kbase[lab.head];const V=[[lab.vx,0],[0,2],[2,1],[1,3]];const a=attention(Q,K,V,lab.mask,lab.temp);el.innerHTML=`<div class="row"><div><h3>注意力，流向哪里？</h3><p class="subtitle">行是 Query，列是 Key。点击行标签切换查询位置。</p></div><span class="tag">${lab.mask?'Causal':'Bidirectional'}</span></div><div class="matrix-wrap"><div class="matrix"><span></span>${tokens.map(t=>`<span class="matrix-label">${t}</span>`).join('')}${a.weights.map((row,i)=>`<button class="matrix-label" data-action="query" data-id="${i}" aria-label="选择查询 ${tokens[i]}">${tokens[i]} ${i===lab.query?'←':''}</button>${row.map((w,j)=>`<div class="cell ${i===lab.query?'selected':''} ${lab.mask&&j>i?'masked':''}" title="Query ${tokens[i]} → Key ${tokens[j]}: ${w.toFixed(4)}" style="${lab.mask&&j>i?'':`background:rgba(117,86,191,${.06+w*.82});color:${w>.45?'white':'#8c75aa'}`}" >${w.toFixed(2)}</div>`).join('')}`).join('')}</div></div><div class="matrix-legend">低权重 <span class="gradient"></span> 高权重 ${lab.mask?'· 斜线区域为不可见位置':''}</div><div class="lab-step"><h3>01 · 当前 Query 与所有 Key</h3><div class="vector-row"><div class="vector-item">Q「${tokens[lab.query]}」<strong>${math(String.raw`[${lab.qx.toFixed(1)},${lab.qy.toFixed(1)}]`)}</strong></div>${K.map((k,i)=>`<div class="vector-item">K「${tokens[i]}」<strong>${math(`[${k.join(', ')}]`)}</strong></div>`).join('')}</div></div><div class="lab-step"><h3>02 · ${math(String.raw`S=QK^{\mathsf T}/(\sqrt2\,\tau)`)} → Softmax</h3><div class="vector-row">${a.scores[lab.query].map((s,i)=>`<div class="vector-item">${tokens[i]}<strong>${math(String.raw`${s===-Infinity?'-\\infty':f(s)}\to ${(a.weights[lab.query][i]*100).toFixed(1)}\%`)}</strong></div>`).join('')}</div><p class="subtitle">${math(String.raw`\sum_j a_{${lab.query+1},j}=${a.weights[lab.query].reduce((s,w)=>s+w,0).toFixed(4)}`)}</p></div><div class="lab-step"><h3>03 · 用权重混合 Value</h3><div class="vector-row" style="margin-bottom:12px">${V.map((v,i)=>`<div class="vector-item">V「${tokens[i]}」<strong>${math(`[${v.join(', ')}]`)}</strong></div>`).join('')}</div><div class="output-vector"><span class="form-label">用当前行的权重混合全部 value（显示值取近似）</span>${mathBlock(String.raw`\begin{aligned}o_{${lab.query+1}}&=\sum_{j=1}^{4}a_{${lab.query+1},j}v_j\\&\approx[${a.out[lab.query].map(f).join(', ')}]\end{aligned}`)}</div></div>`;}
 if(lab.type==='position'){const vals=Array.from({length:lab.dim},(_,i)=>{const x=lab.pos/Math.pow(10000,2*Math.floor(i/2)/lab.dim);return i%2?Math.cos(x):Math.sin(x)});const line=fn=>Array.from({length:125},(_,j)=>`${j===0?'M':'L'}${40+j*4} ${100-fn(j/4)*65}`).join(' ');el.innerHTML=`<h3>每个位置，都有自己的节奏</h3><p class="subtitle">${math(String.raw`\sin p`)} 与 ${math(String.raw`\cos p`)} · 位置 0–31</p><svg viewBox="0 0 560 210" class="position-chart" role="img" aria-label="正弦余弦位置编码曲线，当前选中位置 ${lab.pos}"><path d="M40 25v150h500M40 100h500" stroke="#e9dfef" fill="none"/><path d="${line(Math.sin)}" stroke="#9071c5" stroke-width="2" fill="none"/><path d="${line(Math.cos)}" stroke="#bca3da" stroke-dasharray="4 3" stroke-width="2" fill="none"/><path d="M${40+lab.pos*16} 25v150" stroke="#e0b580" stroke-width="1.5"/><circle cx="${40+lab.pos*16}" cy="${100-Math.sin(lab.pos)*65}" r="5" fill="#9071c5"/><text x="20" y="39" font-size="10" fill="#aa98b7">1</text><text x="18" y="169" font-size="10" fill="#aa98b7">−1</text><text x="40" y="198" font-size="10" fill="#aa98b7">0</text><text x="525" y="198" font-size="10" fill="#aa98b7">31</text></svg><div class="row small muted"><span>━ sin · 偶数维</span><span>┄ cos · 奇数维</span><span>选中 pos = ${lab.pos}</span></div><div class="lab-step"><h3>位置 ${lab.pos} 的 ${lab.dim} 维编码</h3><div class="vector-row">${vals.map((v,i)=>`<div class="vector-item" style="background:${v<0?'#fff2ed':'#f3edf9'};min-width:75px"><span>维度 ${i}</span><strong>${v.toFixed(4)}</strong></div>`).join('')}</div></div>${mathBlock(lessons[2].formula)}`;}
 if(lab.type==='shape'){const {batch:B,tokens:T,model:D,heads:H}=lab;const d=D/H;if(!Number.isInteger(d)){el.innerHTML=`<div class="empty-state">${icon('help',34)}<h3>这个组合无法等宽分头</h3><p>${math(String.raw`d_{\mathrm{model}}/h=${D}/${H}\approx${d.toFixed(2)}`)}，不是整数。<br>请选择可以整除模型维度的头数，再继续观察。</p><p>例如 ${D} 维可以尝试 1、2、4 或 8 个头。</p></div>`;return;}const shapes=[['输入 X / LayerNorm',`(${B}, ${T}, ${D})`],['分头后的 Q / K / V',`(${B}, ${H}, ${T}, ${d})`],['匹配分数 / 权重',`(${B}, ${H}, ${T}, ${T})`],['加权和 AV',`(${B}, ${H}, ${T}, ${d})`],['拼接 + W_O + 残差',`(${B}, ${T}, ${D})`],['FFN 中间层',`(${B}, ${T}, ${D*4})`],['FFN 输出 + 残差',`(${B}, ${T}, ${D})`]];el.innerHTML=`<h3>跟着一个张量，走过整个 Block</h3><p class="subtitle">${math(String.raw`d_{\mathrm{head}}=${D}/${H}=${d}`)} · ${math(String.raw`d_{\mathrm{ff}}=${D*4}`)}</p><div class="flow-shapes">${shapes.map(([t,s],i)=>`<div class="shape-box"><span>0${i+1} · ${t}</span><strong>${math(s)}</strong></div>`).join('')}<div class="shape-box" style="background:#eee8fa"><span>分数元素总数 · ${math(String.raw`BhT^2`)}</span><strong>${(B*H*T*T).toLocaleString()}</strong></div></div><div class="callout"><strong>始终能加回去</strong>两个残差分支的输出都回到 ${math(`(${B},${T},${D})`)}。如果只把序列长度翻倍，注意力分数的元素数量会变为 4 倍。</div>`;}
 if(lab.type==='decode'){const ps=decodeProbs();el.innerHTML=`<div class="row"><div><h3>「我正在学习…」之后</h3><p class="subtitle">固定玩具 logits · 不调用语言模型</p></div><span class="tag">${math(String.raw`\tau=${lab.decodeTemp.toFixed(1)}`)}</span></div>${['Transformer','注意力','数学','烹饪'].map((t,i)=>`<div class="bar-row"><span>${t}</span><div class="bar-track"><span style="width:${ps[i]*100}%"></span></div><strong style="font:12px ui-monospace;color:#977bb5">${(ps[i]*100).toFixed(1)}%</strong></div>`).join('')}${mathBlock(String.raw`\begin{aligned}z&=[2.4,1.6,0.8,0.2]\\p&=\operatorname{softmax}\!\left(\frac{\operatorname{TopK}(z,${lab.topk})}{${lab.decodeTemp.toFixed(1)}}\right)\end{aligned}`)}<div class="lab-step"><h3>最近 ${lab.samples.length} 次独立采样</h3><p class="subtitle">每次使用同一分布重新抽取，样本数量有限时频率不必等于概率。</p><div class="token-buttons" style="margin-top:15px;min-height:45px">${lab.samples.length?lab.samples.map(i=>`<span class="tag">${['Transformer','注意力','数学','烹饪'][i]}</span>`).join(''):'<span class="muted small">点击「采样一次」，看看会抽到哪个候选词。</span>'}</div></div>`;}
 typeset(el);
}
const decodeProbs=()=>softmax([2.4,1.6,.8,.2].map((x,i)=>i<lab.topk?x/lab.decodeTemp:-Infinity));
function markLab(){if(!state.labVisits.includes(lab.type))state.labVisits.push(lab.type);touch();}

let currentRoute='';
function render(){document.body.classList.remove('menu-open');const [section='home',part]=(location.hash.slice(1)||'home').split('/');currentRoute=section;quizConfig=[];chrome(section);const pages={home:()=>home(),courses:()=>courses(part),lesson:()=>lesson(Number(part)),labs:()=>labsPage(part),practice:()=>practice(part),assignments:assignmentList,assignment:()=>assignment(Number(part)),notes:()=>notes(part),settings,resources};$('#main').innerHTML=(!storageOK?`<div class="notice">${esc(storageProblem)} <a href="#settings" style="text-decoration:underline">管理备份</a></div>`:'')+(pages[section]?.()||notFound());if(section==='labs')renderLab();typeset($('#main'));document.title=`${{home:'学习概览',courses:'课程地图',lesson:lessons[Number(part)]?.title,labs:'交互实验室',practice:'练习与复习',assignments:'我的作业',assignment:assignments[Number(part)]?.title,notes:'学习笔记',settings:'本地数据设置',resources:'资源与学习指南'}[section]||'学习空间'} · Attention Lab`;window.scrollTo(0,0);updateStorage();}
window.addEventListener('hashchange',render);
function navigate(path){if(location.hash===`#${path}`)render();else location.hash=path;}

function submitQuiz(event){event.preventDefault();const f=new FormData($('#quiz-form'));const answers={};for(const id of quizConfig){const val=f.get(`q-${id}`);if(val===null||String(val).trim()===''){toast('先完成所有题目，再提交答案。');$(`#question-${id}`).scrollIntoView({behavior:'smooth',block:'center'});return;}answers[id]=String(val);}
 state.attempts.push({answers,date:new Date().toISOString()});if(state.attempts.length>1000)state.attempts.shift();touch();let correct=0;quizFeedback=answers;
 for(const id of quizConfig){const ok=isCorrect(id,answers[id]);if(ok)correct++;const q=qById(id);const answer=q[1]?q[1][q[2]]:q[2];$(`#feedback-${id}`).innerHTML=`<div class="feedback ${ok?'correct':''}"><strong>${ok?'✓ 回答正确':'再想一步 · 正确答案：'+mathText(answer)}</strong>${mathText(q[3])} ${!ok?`<a href="#lesson/${id.split('-')[0]}" style="text-decoration:underline">回看相关课程 →</a>`:''}</div>`;}
 $('#quiz-summary').innerHTML=`<div class="quiz-summary"><strong>${correct===quizConfig.length?'做得好，这次全部答对了。':'已经找到值得巩固的地方。'}</strong><p>本次 ${correct} / ${quizConfig.length} 题正确。${correct<quizConfig.length?'错题已加入复习列表，可阅读解析后重新作答。':'完整课程测验全部正确时，课程进度会自动更新。'}</p></div>`;$('#quiz-form button[type="submit"]').disabled=true;typeset($('#quiz-form'));chrome(currentRoute);$('#quiz-summary').scrollIntoView({behavior:'smooth',block:'center'});}
document.addEventListener('submit',e=>{if(e.target.id==='quiz-form')submitQuiz(e)});

function newNote(lessonId=null,body=''){if(state.notes.length>=500){toast('笔记已达 500 篇，请先导出并整理。');return;}const n={id:'n'+Date.now().toString(36)+'-'+Math.random().toString(36).slice(2,7),title:lessonId!==null?lessons[lessonId].title+' · 学习笔记':'',body,lesson:lessonId,updated:new Date().toISOString()};state.notes.unshift(n);touch();noteSearch='';navigate(`notes/${n.id}`);setTimeout(()=>$('#note-title')?.focus(),30);}
function download(name,text,type='application/json'){const u=URL.createObjectURL(new Blob([text],{type}));const a=document.createElement('a');a.href=u;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(u),1000);}
function modal(title,body,buttons){$('#modal').innerHTML=`<h2>${title}</h2>${body}<div class="actions" style="justify-content:flex-end">${buttons}</div>`;$('#modal').showModal();}
function closeModal(){$('#modal').close();}
let pendingImport=null;
document.addEventListener('click',e=>{
 const el=e.target.closest('[data-action]');if(!el)return;const a=el.dataset.action,id=Number(el.dataset.id);if(a==='submit-quiz')return;e.preventDefault();
 if(a==='skip-main')$('#main').focus();
 if(a==='menu'){document.body.classList.toggle('menu-open');el.setAttribute('aria-expanded',document.body.classList.contains('menu-open'));}
 if(a==='settings')navigate('settings');
 if(a==='mark-read'){if(!state.read.includes(id))state.read.push(id);touch();el.innerHTML=`${icon('check',14)} 已读完本课`;el.className='btn soft';chrome('lesson');$('#quiz').scrollIntoView({behavior:'smooth'});}
 if(a==='scroll-section')$(`#section-${id}`)?.scrollIntoView({behavior:'smooth'});
 if(a==='scroll-quiz')$('#quiz')?.scrollIntoView({behavior:'smooth'});
 if(a==='reset-quiz'){$('#quiz-form').reset();for(const qid of quizConfig)$(`#feedback-${qid}`).innerHTML='';$('#quiz-summary').innerHTML='';$('#quiz-form button[type="submit"]').disabled=false;quizFeedback=null;toast('可以重新独立作答了。');}
 if(a==='preview-note'){const body=$('#note-body'),preview=$('#note-preview');const show=preview.hidden;preview.hidden=!show;body.hidden=show;el.textContent=show?'返回编辑':'预览公式';if(show){preview.textContent=body.value||'还没有写下内容。';typeset(preview);}}
 if(a==='new-note')newNote();
 if(a==='lesson-note')newNote(id);
 if(a==='lab-note')newNote({attention:4,position:2,shape:5,decode:9}[lab.type],`实验：${labs.find(x=>x[0]===lab.type)[1]}\n\n我的预测：\n\n我改变的参数：\n\n实际观察到：\n\n我对原因的解释：\n`);
 if(a==='query'){lab.query=id;[lab.qx,lab.qy]=Qbase[lab.head][id];refreshLabControls();markLab();renderLab();}
 if(a==='reset-lab'){Object.assign(lab,{query:2,head:0,mask:false,temp:1,qx:1,qy:1,vx:1});refreshLabControls();renderLab();toast('实验参数已重置。');}
 if(a==='sample'){const ps=decodeProbs();let r=Math.random(),pick=ps.length-1;for(let i=0;i<ps.length;i++){r-=ps[i];if(r<=0){pick=i;break;}}lab.samples.push(pick);lab.samples=lab.samples.slice(-24);markLab();renderLab();}
 if(a==='clear-samples'){lab.samples=[];renderLab();}
 if(a==='submit-work'){const w=state.work[id];if(!w?.body.trim()||w.body.trim().length<30){toast('请先写下至少 30 个字符的解答或实验记录。');return;}if(!assignments[id].rubric.every((r,i)=>w.checks?.[i])){toast('请对照成果完成全部验收清单。');return;}w.submitted=new Date().toISOString();touch();$('#work-status').textContent=`已于 ${dateText(w.submitted)} 自评提交`;chrome('assignment');toast('作业已保存为自评提交。');}
 if(a==='delete-note'){modal('删除这条笔记？','<p>删除后无法在本站恢复。你可以先导出当前笔记。</p>',btn('取消','close-modal','secondary')+btn('确认删除','confirm-delete-note','danger',`data-id="${el.dataset.id}"`));}
 if(a==='confirm-delete-note'){state.notes=state.notes.filter(n=>n.id!==el.dataset.id);save();closeModal();navigate('notes');toast('笔记已删除。');}
 if(a==='export-note'){const n=state.notes.find(n=>n.id===el.dataset.id);if(n)download('attention-lab-note.txt',`${n.title||'未命名笔记'}\n${n.lesson!==null?'关联课程：'+lessons[n.lesson].title+'\n':''}\n${n.body}`,'text/plain;charset=utf-8');}
 if(a==='export-all'){download(`attention-lab-backup-${day()}.json`,JSON.stringify({app:'attention-lab',version:1,exportedAt:new Date().toISOString(),data:state},null,2));toast('备份已导出，请妥善保存在设备中。');}
 if(a==='export-raw')download('attention-lab-unreadable-backup.json',rawBroken);
 if(a==='import-all'){$('#import-file').value='';$('#import-file').click();}
 if(a==='confirm-import'&&pendingImport){state=pendingImport;pendingImport=null;rawBroken='';storageProblem='';try{knownRaw=localStorage.getItem(STORAGE)}catch{knownRaw=undefined}save();closeModal();render();toast(storageOK?'备份已恢复。':'已读入备份，但本地保存失败，请保留备份文件。');}
 if(a==='reset-data')modal('清空这台设备上的学习记录？','<p>将删除所有笔记、练习记录、作业和学习进度。此操作无法撤销，建议先导出全部记录。</p>',btn('取消','close-modal','secondary')+btn('确认清空','confirm-reset','danger'));
 if(a==='confirm-reset'){state=blank();rawBroken='';storageProblem='';try{knownRaw=localStorage.getItem(STORAGE)}catch{knownRaw=undefined}save();closeModal();navigate('home');toast('本地学习记录已重置。');}
 if(a==='close-modal'){pendingImport=null;closeModal();}
 if(a==='download-python')download('attention_lab_reference.py',pythonStarter,'text/x-python;charset=utf-8');
 if(a==='search'){modal('找到你想理解的概念','<label class="visually-hidden" for="course-search">搜索课程</label><input class="field" id="course-search" placeholder="试试：Q/K/V、位置、训练…"><div id="course-results" style="max-height:330px;overflow:auto;margin:15px 0"></div>',btn('关闭','close-modal','secondary'));searchCourses('');$('#course-search').focus();}
});
function refreshLabControls(){const el=$('.lab-controls');if(el){el.innerHTML=labControls(lab.type);typeset(el);}}
function workRecord(id){return state.work[id]||(state.work[id]={body:'',checks:[false,false,false,false],submitted:null,updated:new Date().toISOString()});}
document.addEventListener('input',e=>{const el=e.target;
 if(el.dataset.lab){const k=el.dataset.lab;lab[k]=Number(el.value);if($(`#${k}-label`))$(`#${k}-label`).textContent=el.value;if(k==='decodeTemp'||k==='topk')lab.samples=[];markLab();renderLab();}
 if(el.id==='work-body'){const w=workRecord(Number(el.dataset.id));w.body=el.value;w.updated=new Date().toISOString();w.submitted=null;touch();$('#work-status').textContent='草稿 · 输入后自动保存';}
 if(el.id==='note-title'||el.id==='note-body'){const n=state.notes.find(n=>n.id===el.dataset.id);if(n){n[el.id==='note-title'?'title':'body']=el.value;n.updated=new Date().toISOString();touch();$('#note-items').innerHTML=noteItems(n.id);}}
 if(el.id==='note-search'){noteSearch=el.value;$('#note-items').innerHTML=noteItems($('#note-title')?.dataset.id);}
 if(el.id==='course-search')searchCourses(el.value);
});
function searchCourses(query){const q=query.toLowerCase();$('#course-results').innerHTML=lessons.filter(l=>(l.title+l.tag+l.en+l.sections.flat().join('').replace(/<[^>]*>/g,' ')).toLowerCase().includes(q)).map(l=>`<a class="search-result" href="#lesson/${l.id}">${String(l.id+1).padStart(2,'0')} · ${l.title}<small style="display:block;color:var(--muted)">${l.tag}</small></a>`).join('')||'<p class="subtitle">没有匹配的课程，试试更短的关键词。</p>';}
$('#modal').addEventListener('click',e=>{if(e.target.closest('a[href^="#"]'))closeModal();});
document.addEventListener('change',async e=>{const el=e.target;
 if(el.id==='practice-select')navigate('practice/'+el.value);
 if(el.id==='head-select'){lab.head=Number(el.value);[lab.qx,lab.qy]=Qbase[lab.head][lab.query];refreshLabControls();markLab();renderLab();}
 if(el.id==='causal'){lab.mask=el.checked;markLab();renderLab();}
 if(el.id==='dim-select'){lab.dim=Number(el.value);markLab();renderLab();}
 if(el.id==='model-select'){lab.model=Number(el.value);markLab();renderLab();}
 if(el.dataset.workCheck!==undefined){const w=workRecord(Number(el.dataset.workCheck));w.checks[Number(el.value)]=el.checked;w.submitted=null;w.updated=new Date().toISOString();touch();$('#work-status').textContent='草稿 · 验收清单已更新';}
 if(el.id==='note-lesson'){const n=state.notes.find(n=>n.id===el.dataset.id);if(n){n.lesson=el.value===''?null:Number(el.value);n.updated=new Date().toISOString();touch();$('#note-items').innerHTML=noteItems(n.id);}}
 if(el.id==='import-file'){const file=el.files[0];if(!file)return;try{if(file.size>10*1024*1024)throw Error('备份文件超过 10 MB');const x=JSON.parse(await file.text());if(x.app!=='attention-lab'||x.version!==1)throw Error('不是兼容的 Attention Lab 备份');pendingImport=validateData(x.data);modal('恢复这个学习备份？',`<p>备份中有 <b>${pendingImport.notes.length} 篇笔记</b>、${pendingImport.attempts.length} 次答题记录、${Object.keys(pendingImport.work).length} 份作业。<br><br>恢复会替换当前浏览器的全部学习记录。请先确认已导出需要保留的内容。</p>`,btn('取消','close-modal','secondary')+btn('确认替换并恢复','confirm-import','primary'));}catch(err){pendingImport=null;toast('无法导入：'+err.message);}}
});
// Deliberately no network synchronization; warn if another tab changes the local dataset.
window.addEventListener('storage',e=>{if(e.key===STORAGE&&e.newValue!==knownRaw){storageOK=false;storageProblem='另一个标签页已更新记录，本页暂停保存。请导出本页内容后刷新。';updateStorage();toast(storageProblem);}});
render();
